package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class PowerNumberListsTest {
 private List<String> independentlySolve(String id,int upper){List<String> values=new ArrayList<>();for(int b=0;b<=upper;b++)values.add(""+(id.equals(PowerNumberLists.SQUARE)?b*b:b*b*b));return values;}
 @Test public void allVisibleBoundsCheckCompleteLearnerLists(){
  for(String id:List.of(PowerNumberLists.SQUARE,PowerNumberLists.CUBE)){Set<String>seen=new HashSet<>();for(int upper=0;upper<=10;upper++){Question q=PowerNumberLists.indexed(id,upper);assertEquals(upper,PowerNumberLists.read(q));assertTrue(seen.add(q.signature()));q.answers=new String[]{"poison"};q.expression="poison";List<String> solution=independentlySolve(id,upper);assertTrue(PowerNumberLists.check(q,solution).correct());if(upper>0)assertEquals(-1,PowerNumberLists.check(q,solution.subList(0,solution.size()-1)).index);assertEquals(0,PowerNumberLists.check(q,List.of("2")).index);assertEquals(1,PowerNumberLists.check(q,List.of("0","0")).index);if(upper>0)assertEquals(1,PowerNumberLists.check(q,List.of("1","0")).index);assertEquals(Checker.Status.INPUT_NEEDED,PowerNumberLists.check(q,List.of("")).status);assertTrue(q.choices.isEmpty());}assertEquals(11,seen.size());}
  assertEquals(List.of("0","1","4","9","16","25","36","49","64","81","100"),independentlySolve(PowerNumberLists.SQUARE,10));assertEquals("1000",independentlySolve(PowerNumberLists.CUBE,10).get(10));
 }
 @Test public void helpOnlyDefinesExponentAndNeverRevealsList(){for(String id:List.of(PowerNumberLists.SQUARE,PowerNumberLists.CUBE))for(int upper=0;upper<=10;upper++){Question q=PowerNumberLists.make(id,upper);q.answers=new String[]{"poison"};PowerNumberLists.attach(q);assertEquals(1,q.studyGuide.frames.size());assertFalse(q.studyGuide.transfer);assertEquals("지수 = ",q.studyGuide.frames.get(0).before);assertEquals(id.equals(PowerNumberLists.SQUARE)?"2":"3",q.studyGuide.frames.get(0).expected);HelpPlan help=HelpPlan.forQuestion(q);assertFalse(help.canTransfer());assertEquals(List.of(""),help.restore(null,q.id).entries);assertFalse(q.studyGuide.frames.get(0).instruction.contains("11개"));}}
 @Test public void finiteSupplyFreshUntilAllPublicBoundsThenOldest(){for(String id:List.of(PowerNumberLists.SQUARE,PowerNumberLists.CUBE)){CurriculumLimits limits=new CurriculumLimits("minGiven=0;maxGiven=10;maxResult=1000;nonnegative=true");Map<String,Integer>recent=new LinkedHashMap<>();Set<Integer>seen=new HashSet<>();Random pinned=new Random(){@Override public int nextInt(int bound){return 0;}};for(int i=0;i<11;i++){Question q=PowerNumberLists.next(id,pinned,limits,recent);assertTrue(limits.allows(q));assertTrue(seen.add(PowerNumberLists.read(q)));recent.put(q.signature(),i);}assertEquals(11,seen.size());assertEquals(0,(int)recent.get(PowerNumberLists.next(id,pinned,limits,recent).signature()));}}
 @Test public void malformedRangesAndMembersReject(){for(String id:List.of(PowerNumberLists.SQUARE,PowerNumberLists.CUBE)){Question q=PowerNumberLists.make(id,3);assertEquals(0,PowerNumberLists.check(q,List.of("16")).index);q.prompt=q.prompt.replace("3 이하","11 이하");assertEquals(-1,PowerNumberLists.read(q));try{PowerNumberLists.make(id,11);fail();}catch(IllegalArgumentException expected){}try{PowerNumberLists.indexed(id,-1);fail();}catch(IllegalArgumentException expected){}}}
}
